BEGIN IMMEDIATE;
CREATE TABLE audit_heads(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,slot INTEGER NOT NULL CHECK(slot=1),seq INTEGER NOT NULL,head_digest TEXT NOT NULL CHECK(length(head_digest)=64),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,slot));
CREATE TABLE audit_ledger(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,seq INTEGER NOT NULL CHECK(seq>0),operation_id TEXT NOT NULL,subject_id TEXT NOT NULL,action TEXT NOT NULL,resource_json TEXT NOT NULL,outcome TEXT NOT NULL,previous_digest TEXT NOT NULL,entry_digest TEXT NOT NULL,entry_json TEXT NOT NULL CHECK(length(CAST(entry_json AS BLOB))<=65536),created_at_ms INTEGER NOT NULL,PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,seq),UNIQUE(organization_id,tenant_id,project_id,agent_uid,operation_id),FOREIGN KEY(tenant_id,project_id,agent_uid) REFERENCES agents(tenant_id,project_id,uid));
CREATE TRIGGER audit_immutable_update BEFORE UPDATE ON audit_ledger BEGIN SELECT RAISE(ABORT,'immutable audit'); END;
CREATE TRIGGER audit_immutable_delete BEFORE DELETE ON audit_ledger BEGIN SELECT RAISE(ABORT,'immutable audit'); END;
CREATE TABLE quota_accounts(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,metric TEXT NOT NULL,budget INTEGER NOT NULL CHECK(budget>=0),consumed INTEGER NOT NULL DEFAULT 0 CHECK(consumed>=0),reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0),revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0),window_start_ms INTEGER NOT NULL,window_end_ms INTEGER NOT NULL CHECK(window_end_ms>window_start_ms),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,metric,window_start_ms),FOREIGN KEY(tenant_id,project_id,agent_uid) REFERENCES agents(tenant_id,project_id,uid),CHECK(consumed+reserved<=budget));
CREATE TABLE quota_ledger(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,operation_id TEXT NOT NULL,metric TEXT NOT NULL,window_start_ms INTEGER NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0),state TEXT NOT NULL CHECK(state IN ('reserved','consumed','released')),run_id TEXT NOT NULL REFERENCES runs(id),created_at_ms INTEGER NOT NULL,updated_at_ms INTEGER NOT NULL,PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,operation_id),FOREIGN KEY(organization_id,tenant_id,project_id,agent_uid,metric,window_start_ms) REFERENCES quota_accounts(organization_id,tenant_id,project_id,agent_uid,metric,window_start_ms));
INSERT INTO schema_migrations VALUES(28,CAST(strftime('%s','now') AS INTEGER)*1000);
COMMIT;
